std::vector<std::vector<int>> BoostEquipment::GetLevel80ItemList(uint32 classId, uint8 specialization, uint8 equipmentTier)
{
  if (specialization > 2)
  {
    specialization = 0;
  }
  if (equipmentTier > 2)
  {
    equipmentTier = 0;
  }

  const BoostSet *set = nullptr;
  switch (classId)
  {
  case CLASS_WARRIOR:
    set = &warriorSets[equipmentTier][specialization];
    break;
  case CLASS_PALADIN:
    set = &paladinSets[equipmentTier][specialization];
    break;
  case CLASS_HUNTER:
    set = &hunterSets[equipmentTier][specialization];
    break;
  case CLASS_ROGUE:
    set = &rogueSets[equipmentTier][specialization];
    break;
  case CLASS_PRIEST:
    set = &priestSets[equipmentTier][specialization];
    break;
  case CLASS_DEATH_KNIGHT:
    set = &dkSets[equipmentTier][specialization];
    break;
  case CLASS_SHAMAN:
    set = &shamanSets[equipmentTier][specialization];
    break;
  case CLASS_MAGE:
    set = &mageSets[equipmentTier][specialization];
    break;
  case CLASS_WARLOCK:
    set = &warlockSets[equipmentTier][specialization];
    break;
  case CLASS_DRUID:
    set = &druidSets[equipmentTier][specialization];
    break;
  default:
    break;
  }

  std::vector<std::vector<int>> itemList;
  if (!set)
  {
    return itemList;
  }

  for (int i = 0; i < 18; ++i)
  {
    itemList.push_back({set->item[i][0], set->item[i][1]});
  }
  return itemList;
}

